WITH desired AS (SELECT p.id_user,RANK() OVER(ORDER BY p.points DESC)::integer rank FROM public.user_points p JOIN public."user" u ON u.id=p.id_user WHERE NOT u.banned AND EXISTS(SELECT 1 FROM public.record r WHERE r.id_user=u.id AND r.date_created>=now()-interval '6 months')) SELECT count(*)::bigint AS count FROM desired JOIN public.user_points p USING(id_user) WHERE p.rank<>desired.rank
